<?php

/*
 * slipstream-release.php — GENERATED by `composer stub:build` from src/Release/Core
 * and stubs/src/release-main.php. Do not edit; edit those and rebuild.
 *
 * A single file with no dependencies beyond PHP's sodium, zlib and hash
 * extensions: verifies and unpacks a release on a node that has no
 * Slipstream code yet (slipstream-bootstrap.sh), and signs and publishes
 * one from CI without installing or booting anything.
 */

namespace Slipstream\Release\Core {

// — Signer.php

/**
 * Something that signs a message with an Ed25519 key: a sodium secret key, or
 * AWS KMS through its CLI. Nodes never sign; they verify with the public key.
 */
interface Signer
{
    /**
     * The raw 64-byte Ed25519 signature of the message.
     */
    public function sign(string $message): string;

    /**
     * The raw 32-byte public key.
     */
    public function publicKey(): string;

    /**
     * The id nodes look the key up by: given, or derived from the public key.
     */
    public function keyId(): string;
}

// — ArtifactRefused.php

/**
 * A release a node will not take, and at which stage of checking it it found
 * out: pointer, statement, manifest, php, archive or files. Refused content
 * is deleted at once, never kept for inspection — there is nothing in it to
 * re-run, and unverified bytes stay off a node.
 */
final class ArtifactRefused extends \RuntimeException
{
    public function __construct(
        public readonly string $stage,
        public readonly string $reason,
        public readonly ?string $sha = null,
        /** @var array<string, scalar|null> */
        public readonly array $context = [],
    ) {
        parent::__construct("Refusing artifact ({$stage}): {$reason}");
    }
}

// — Baseline.php

/**
 * The caches a node generates into a release (bootstrap/cache/*.php: config,
 * routes, services, packages, events) are executable and loaded on every
 * request, but no manifest can list them: they hold the node's own values.
 * The deploy records their hashes just before the swap, and verification
 * compares against that record, so a change after the deploy shows up.
 */
final class Baseline
{
    public const FORMAT = 1;

    public const DIRECTORY = 'bootstrap/cache';

    /** The record's name inside the release's .slipstream directory. */
    public const FILE = 'generated.json';

    /**
     * @return array<string, array{0: string, 1: int}>  path => [sha256, size]; a symlink is ['symlink', 0]
     */
    public static function record(string $release): array
    {
        $files = [];
        $dir = rtrim($release, '/\\').'/'.self::DIRECTORY;

        foreach (@scandir($dir, SCANDIR_SORT_ASCENDING) ?: [] as $name) {
            if (! str_ends_with($name, '.php')) {
                continue;
            }
            $file = $dir.'/'.$name;
            if (is_link($file)) {
                $files[self::DIRECTORY.'/'.$name] = ['symlink', 0];
            } elseif (is_file($file)) {
                $files[self::DIRECTORY.'/'.$name] = [(string) hash_file('sha256', $file), (int) filesize($file)];
            }
        }

        return $files;
    }

    /**
     * The paths that changed, appeared or went missing since the record.
     *
     * @param  array<string, array{0: string, 1: int}>  $baseline
     * @return list<string>
     */
    public static function compare(string $release, array $baseline): array
    {
        $now = self::record($release);
        $changed = [];

        foreach ($baseline as $path => $entry) {
            if (($now[$path] ?? null) !== $entry) {
                $changed[] = (string) $path;
            }
        }
        foreach (array_keys($now) as $path) {
            if (! isset($baseline[$path])) {
                $changed[] = (string) $path;
            }
        }

        sort($changed, SORT_STRING);

        return array_values(array_unique($changed));
    }

    /**
     * @param  array<string, array{0: string, 1: int}>  $files
     */
    public static function toJson(array $files): string
    {
        ksort($files, SORT_STRING);

        return json_encode(['format' => self::FORMAT, 'files' => $files === [] ? new \stdClass : $files], JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR)."\n";
    }

    /**
     * @return array<string, array{0: string, 1: int}>|null  null when the JSON is not a baseline
     */
    public static function fromJson(string $json): ?array
    {
        $data = json_decode($json, true);
        if (! is_array($data) || ($data['format'] ?? null) !== self::FORMAT || ! is_array($data['files'] ?? null)) {
            return null;
        }

        $files = [];
        foreach ($data['files'] as $path => $entry) {
            $path = (string) $path;
            if (! str_starts_with($path, self::DIRECTORY.'/') || ! is_array($entry) || count($entry) !== 2
                || ! is_string($entry[0] ?? null) || ! is_int($entry[1] ?? null)) {
                return null;
            }
            $files[$path] = [$entry[0], $entry[1]];
        }

        return $files;
    }
}

// — Envelope.php

/**
 * A signed document: {"alg":"ed25519","key_id":…,"payload":<base64 of the
 * exact JSON bytes signed>,"signature":<base64>}. The signature covers a
 * domain prefix plus the payload bytes, so a pointer can never pass as a
 * manifest statement or the other way round; verification uses the bytes as
 * sent, so there is no canonical form to disagree about. The payload stays
 * under KMS's 4096-byte raw-message cap, which is why the manifest itself is
 * bound by hash rather than signed.
 */
final class Envelope
{
    public const DOMAIN_POINTER = "slipstream-pointer\n";

    public const DOMAIN_MANIFEST = "slipstream-manifest\n";

    public const MAX_PAYLOAD = KmsSigner::MAX_MESSAGE;

    public const MAX_ENVELOPE = 65536;

    /**
     * The bytes a payload is signed as: keys sorted at every level, slashes
     * unescaped, no whitespace.
     *
     * @param  array<string, mixed>  $payload
     */
    public static function payloadBytes(array $payload): string
    {
        return json_encode(self::sorted($payload), JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_THROW_ON_ERROR);
    }

    /**
     * Sign a payload under a domain; returns the envelope's JSON.
     *
     * @param  array<string, mixed>  $payload
     */
    public static function encode(array $payload, string $domain, Signer $signer): string
    {
        $bytes = self::payloadBytes($payload);

        if (strlen($bytes) > self::MAX_PAYLOAD) {
            throw new \InvalidArgumentException('payload exceeds '.self::MAX_PAYLOAD.' bytes');
        }

        return json_encode([
            'alg' => 'ed25519',
            'key_id' => $signer->keyId(),
            'payload' => base64_encode($bytes),
            'signature' => base64_encode($signer->sign($domain.$bytes)),
        ], JSON_THROW_ON_ERROR)."\n";
    }

    /**
     * Verify an envelope under a domain against the trusted keys.
     *
     * @return array{payload: array<string, mixed>, key_id: string}
     *
     * @throws SignatureException with the one reason it does not verify
     */
    public static function verify(string $envelope, string $domain, Keys $keys): array
    {
        if (strlen($envelope) > self::MAX_ENVELOPE) {
            throw new SignatureException('not a signature envelope');
        }

        $decoded = json_decode($envelope, true);
        if (! is_array($decoded)
            || ! is_string($decoded['payload'] ?? null)
            || ! is_string($decoded['signature'] ?? null)
            || ! is_string($decoded['key_id'] ?? null)) {
            throw new SignatureException('not a signature envelope');
        }

        if (($decoded['alg'] ?? null) !== 'ed25519') {
            throw new SignatureException('alg is not ed25519');
        }

        $bytes = base64_decode($decoded['payload'], true);
        $signature = base64_decode($decoded['signature'], true);
        if ($bytes === false || $signature === false || strlen($signature) !== SODIUM_CRYPTO_SIGN_BYTES) {
            throw new SignatureException('not a signature envelope');
        }

        if (strlen($bytes) > self::MAX_PAYLOAD) {
            throw new SignatureException('payload exceeds '.self::MAX_PAYLOAD.' bytes');
        }

        $publicKey = $keys->find($decoded['key_id']);
        if ($publicKey === null) {
            throw new SignatureException(sprintf(
                'unknown key id "%s" (configured: %s)',
                $decoded['key_id'],
                $keys->count() > 0 ? implode(', ', $keys->ids()) : 'none'
            ));
        }

        if (! sodium_crypto_sign_verify_detached($signature, $domain.$bytes, $publicKey)) {
            throw new SignatureException('signature does not verify');
        }

        $payload = json_decode($bytes, true);
        if (! is_array($payload)) {
            throw new SignatureException('payload is not JSON');
        }

        return ['payload' => $payload, 'key_id' => $decoded['key_id']];
    }

    /**
     * @param  array<string, mixed>  $value
     * @return array<string, mixed>
     */
    private static function sorted(array $value): array
    {
        if (! array_is_list($value)) {
            ksort($value, SORT_STRING);
        }

        foreach ($value as $key => $item) {
            if (is_array($item)) {
                $value[$key] = self::sorted($item);
            }
        }

        return $value;
    }
}

// — Keys.php

/**
 * The public keys a node trusts, as SLIPSTREAM_RELEASE_PUBLIC_KEYS gives
 * them: `id:base64` entries, comma-separated, at most two so a key can be
 * rotated (add the new one, switch CI, drop the old). `file:<path>` names a
 * file holding the same list, for a key baked into an image.
 */
final class Keys
{
    public const MAX = 2;

    /**
     * @param  array<string, string>  $keys  id => raw 32-byte key
     */
    private function __construct(private array $keys) {}

    /**
     * @param  list<string>|string  $entries
     */
    public static function parse(array|string $entries, int $max = self::MAX): self
    {
        if (is_string($entries)) {
            $entries = trim($entries);
            if (str_starts_with($entries, 'file:')) {
                $path = substr($entries, 5);
                // A relative path resolves against the working directory,
                // which for artisan is the release: the trust anchors would
                // come from the archive they are meant to check.
                if (! self::isAbsolute($path)) {
                    throw new \InvalidArgumentException("SLIPSTREAM_RELEASE_PUBLIC_KEYS=file:{$path} is a relative path; name the key file by an absolute path outside the release, e.g. file:/etc/slipstream/release-keys.");
                }
                $contents = is_file($path) ? @file_get_contents($path) : false;
                if ($contents === false) {
                    throw new \InvalidArgumentException("SLIPSTREAM_RELEASE_PUBLIC_KEYS names {$path}, which cannot be read.");
                }
                $entries = $contents;
            }
            $entries = preg_split('/[\s,]+/', $entries) ?: [];
        }

        $keys = [];

        foreach ($entries as $entry) {
            $entry = trim((string) $entry);
            if ($entry === '') {
                continue;
            }

            [$id, $encoded] = array_pad(explode(':', $entry, 2), 2, null);
            if ($encoded === null || preg_match('/^[A-Za-z0-9._-]{1,64}$/', (string) $id) !== 1) {
                throw new \InvalidArgumentException("\"{$entry}\" is not a public key entry; use id:base64 (slipstream:artifact keygen prints one).");
            }

            $raw = base64_decode($encoded, true);
            if ($raw === false || strlen($raw) !== SODIUM_CRYPTO_SIGN_PUBLICKEYBYTES) {
                throw new \InvalidArgumentException("The public key \"{$id}\" is not a base64 Ed25519 key (32 bytes).");
            }
            if (isset($keys[$id])) {
                throw new \InvalidArgumentException("The public key id \"{$id}\" is listed twice.");
            }

            $keys[$id] = $raw;
        }

        if (count($keys) > $max) {
            throw new \InvalidArgumentException('At most '.$max.' public keys: the one in use and the one it is rotating to.');
        }

        return new self($keys);
    }

    public static function none(): self
    {
        return new self([]);
    }

    public static function isAbsolute(string $path): bool
    {
        return str_starts_with($path, '/')
            || str_starts_with($path, '\\\\')
            || preg_match('#^[A-Za-z]:[\\\\/]#', $path) === 1;
    }

    /**
     * The id a key gets when nobody names it: the first 8 hex characters of
     * the public key's SHA-256.
     */
    public static function deriveId(string $publicKey): string
    {
        return substr(hash('sha256', $publicKey), 0, 8);
    }

    /**
     * One entry as SLIPSTREAM_RELEASE_PUBLIC_KEYS wants it.
     */
    public static function format(string $id, string $publicKey): string
    {
        return $id.':'.base64_encode($publicKey);
    }

    public function find(string $id): ?string
    {
        return $this->keys[$id] ?? null;
    }

    /**
     * @return list<string>
     */
    public function ids(): array
    {
        return array_keys($this->keys);
    }

    public function count(): int
    {
        return count($this->keys);
    }

    /**
     * These keys plus one more (the publisher verifies what it just signed
     * with its own key, which the node list need not hold yet).
     */
    public function with(string $id, string $publicKey): self
    {
        return new self($this->keys + [$id => $publicKey]);
    }
}

// — KmsSigner.php

/**
 * Signs with an AWS KMS asymmetric key (spec ECC_NIST_EDWARDS25519) through
 * the AWS CLI, so the private key never leaves KMS and every signature is a
 * CloudTrail event. `kms:<key id, ARN or alias>`. The algorithm is
 * ED25519_SHA_512 over the RAW message, which KMS caps at 4096 bytes — the
 * reason every signed payload stays small and the manifest is bound by hash.
 */
final class KmsSigner implements Signer
{
    public const ALGORITHM = 'ED25519_SHA_512';

    public const MAX_MESSAGE = 4096;

    /** The DER SubjectPublicKeyInfo prefix of an Ed25519 key: 12 bytes, then the 32-byte key. */
    public const SPKI_PREFIX = '302a300506032b6570032100';

    /** @var (\Closure(list<string>): string)|null */
    private ?\Closure $run;

    private ?string $publicKey = null;

    /**
     * @param  (\Closure(list<string>): string)|null  $run  runs an argv, returns stdout, throws on failure; the real CLI when null
     */
    public function __construct(private string $key, private ?string $keyId = null, ?\Closure $run = null)
    {
        $this->run = $run;
    }

    public static function fromSpec(string $spec, ?string $keyId = null, ?\Closure $run = null): self
    {
        $spec = trim($spec);
        if (! str_starts_with($spec, 'kms:') || trim(substr($spec, 4)) === '') {
            throw new \InvalidArgumentException('A KMS signing key is kms:<key id, ARN or alias>.');
        }

        return new self(trim(substr($spec, 4)), $keyId, $run);
    }

    public function sign(string $message): string
    {
        if (strlen($message) > self::MAX_MESSAGE) {
            throw new \InvalidArgumentException('KMS signs at most '.self::MAX_MESSAGE.' bytes of raw message.');
        }

        $file = tempnam(sys_get_temp_dir(), 'ss-sign-');
        if ($file === false || file_put_contents($file, $message) !== strlen($message)) {
            throw new \RuntimeException('Cannot write the message to sign to a temporary file.');
        }

        try {
            $out = $this->aws(['kms', 'sign', '--key-id', $this->key, '--signing-algorithm', self::ALGORITHM,
                '--message-type', 'RAW', '--message', 'fileb://'.$file, '--output', 'json']);
        } finally {
            @unlink($file);
        }

        $signature = base64_decode((string) (self::decode($out)['Signature'] ?? ''), true);
        if ($signature === false || strlen($signature) !== SODIUM_CRYPTO_SIGN_BYTES) {
            throw new \RuntimeException('aws kms sign returned no 64-byte signature; is the key an ECC_NIST_EDWARDS25519 key?');
        }

        return $signature;
    }

    public function publicKey(): string
    {
        if ($this->publicKey !== null) {
            return $this->publicKey;
        }

        $der = base64_decode((string) (self::decode($this->aws(['kms', 'get-public-key', '--key-id', $this->key, '--output', 'json']))['PublicKey'] ?? ''), true);
        $prefix = hex2bin(self::SPKI_PREFIX);

        if ($der === false || strlen($der) !== 12 + SODIUM_CRYPTO_SIGN_PUBLICKEYBYTES || substr($der, 0, 12) !== $prefix) {
            throw new \RuntimeException('The KMS key is not an Ed25519 key: expected a 44-byte SubjectPublicKeyInfo with the Ed25519 OID.');
        }

        return $this->publicKey = substr($der, 12);
    }

    public function keyId(): string
    {
        return $this->keyId ??= Keys::deriveId($this->publicKey());
    }

    /**
     * @param  list<string>  $args
     */
    private function aws(array $args): string
    {
        $run = $this->run ?? self::cli(...);

        return $run(['aws', ...$args]);
    }

    /**
     * Run an argv without a shell; stdout on success, an exception carrying
     * stderr otherwise.
     *
     * @param  list<string>  $argv
     */
    public static function cli(array $argv): string
    {
        $process = @proc_open($argv, [0 => ['file', PHP_OS_FAMILY === 'Windows' ? 'NUL' : '/dev/null', 'r'], 1 => ['pipe', 'w'], 2 => ['pipe', 'w']], $pipes);
        if (! is_resource($process)) {
            throw new \RuntimeException('Cannot run '.$argv[0].'; is the AWS CLI installed?');
        }

        $stdout = (string) stream_get_contents($pipes[1]);
        $stderr = (string) stream_get_contents($pipes[2]);
        fclose($pipes[1]);
        fclose($pipes[2]);
        $code = proc_close($process);

        if ($code !== 0) {
            throw new \RuntimeException(implode(' ', array_slice($argv, 0, 3)).' failed (exit '.$code.'): '.trim($stderr));
        }

        return $stdout;
    }

    /**
     * @return array<string, mixed>
     */
    private static function decode(string $json): array
    {
        $decoded = json_decode($json, true);

        if (! is_array($decoded)) {
            throw new \RuntimeException('The AWS CLI returned something other than JSON: '.substr(trim($json), 0, 200));
        }

        return $decoded;
    }
}

// — Manifest.php

/**
 * What a release contains: every file with its SHA-256 and size, the archive
 * that carries them, the PHP it was built with, and the paths a node writes
 * itself after unpacking (which a later verification must not count as
 * drift). Unsigned; bound to its statement by hash and size.
 */
final class Manifest
{
    public const FORMAT = 1;

    public const MAX_PATH = 4096;

    /** What a node writes into a release itself; publish lists these unless told otherwise. */
    public const DEFAULT_GENERATED = ['bootstrap/cache', 'public/storage', 'public/hot'];

    /** Files the deploy itself adds to every release. */
    public const NODE_WRITTEN = ['RELEASE_SHA', '.slipstream'];

    /** What the deploy replaces with links to the shared copies, besides the shared paths. */
    public const NODE_LINKED = ['storage', '.env', 'auth.json'];

    /**
     * @param  array<string, array{0: string, 1: int}>  $files  path => [sha256, size], sorted by path
     * @param  list<string>  $generated
     */
    public function __construct(
        public readonly string $slipstream,
        public readonly string $environment,
        public readonly string $sha,
        public readonly string $ref,
        public readonly string $builtAt,
        public readonly string $php,
        public readonly string $archiveName,
        public readonly string $archiveSha256,
        public readonly int $archiveSize,
        public readonly int $unpackedBytes,
        public readonly int $entries,
        public readonly array $files,
        public readonly array $generated,
    ) {}

    /**
     * @throws ArtifactRefused when the JSON is not a manifest
     */
    public static function fromJson(string $json): self
    {
        $refuse = fn (string $why) => throw new ArtifactRefused('manifest', 'the manifest is malformed: '.$why);

        $data = json_decode($json, true);
        if (! is_array($data)) {
            $refuse('not JSON');
        }
        if (($data['format'] ?? null) !== self::FORMAT) {
            $refuse('format '.json_encode($data['format'] ?? null).' is not '.self::FORMAT);
        }

        foreach (['slipstream', 'environment', 'sha', 'ref', 'built_at', 'php'] as $field) {
            if (! is_string($data[$field] ?? null) || $data[$field] === '' || strlen($data[$field]) > 255) {
                $refuse($field);
            }
        }
        if (preg_match('/^[0-9a-f]{40}$/', $data['sha']) !== 1) {
            $refuse('sha');
        }
        if (preg_match('/^\d+\.\d+\.\d+/', $data['php']) !== 1) {
            $refuse('php');
        }

        $archive = $data['archive'] ?? null;
        if (! is_array($archive)
            || ! is_string($archive['name'] ?? null) || ! self::validPath($archive['name']) || str_contains($archive['name'], '/')
            || ! is_string($archive['sha256'] ?? null) || preg_match('/^[0-9a-f]{64}$/', $archive['sha256']) !== 1
            || ! is_int($archive['size'] ?? null) || $archive['size'] < 0
            || ! is_int($archive['unpacked_bytes'] ?? null) || $archive['unpacked_bytes'] < 0
            || ! is_int($archive['entries'] ?? null) || $archive['entries'] < 0) {
            $refuse('archive');
        }

        $files = $data['files'] ?? null;
        if (! is_array($files)) {
            $refuse('files');
        }
        $seen = [];
        $clean = [];
        foreach ($files as $path => $entry) {
            // json_decode turns a digit-only name ("404") into an int key.
            $path = (string) $path;
            if (! self::validPath($path)) {
                $refuse('file path '.json_encode($path, JSON_UNESCAPED_SLASHES));
            }
            if (! is_array($entry) || ! array_is_list($entry) || count($entry) !== 2
                || ! is_string($entry[0]) || preg_match('/^[0-9a-f]{64}$/', $entry[0]) !== 1
                || ! is_int($entry[1]) || $entry[1] < 0) {
                $refuse("file {$path}");
            }
            $folded = strtolower($path);
            if (isset($seen[$folded])) {
                $refuse("files {$path} and {$seen[$folded]} differ only in case");
            }
            $seen[$folded] = $path;
            $clean[$path] = [$entry[0], $entry[1]];
        }
        ksort($clean, SORT_STRING);

        $generated = $data['generated'] ?? [];
        if (! is_array($generated) || ! array_is_list($generated)) {
            $refuse('generated');
        }
        foreach ($generated as $path) {
            if (! is_string($path) || ! self::validPath($path)) {
                $refuse('generated path '.json_encode($path, JSON_UNESCAPED_SLASHES));
            }
        }

        return new self(
            $data['slipstream'], $data['environment'], $data['sha'], $data['ref'], $data['built_at'], $data['php'],
            $archive['name'], $archive['sha256'], $archive['size'], $archive['unpacked_bytes'], $archive['entries'],
            $clean, array_values($generated),
        );
    }

    /**
     * Deterministic: the same release always serialises to the same bytes.
     */
    public function toJson(): string
    {
        $files = $this->files;
        ksort($files, SORT_STRING);

        return json_encode([
            'format' => self::FORMAT,
            'slipstream' => $this->slipstream,
            'environment' => $this->environment,
            'sha' => $this->sha,
            'ref' => $this->ref,
            'built_at' => $this->builtAt,
            'php' => $this->php,
            'archive' => [
                'name' => $this->archiveName,
                'sha256' => $this->archiveSha256,
                'size' => $this->archiveSize,
                'unpacked_bytes' => $this->unpackedBytes,
                'entries' => $this->entries,
            ],
            'files' => $files === [] ? new \stdClass : $files,
            'generated' => $this->generated,
        ], JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_THROW_ON_ERROR)."\n";
    }

    /**
     * The PHP series the release was built with: "8.4".
     */
    public function phpSeries(): string
    {
        return implode('.', array_slice(explode('.', $this->php), 0, 2));
    }

    /**
     * A release-relative path: forward slashes, no empty, `.` or `..`
     * segments, no leading slash, no NUL or backslash.
     */
    public static function validPath(string $path): bool
    {
        if ($path === '' || strlen($path) > self::MAX_PATH || $path[0] === '/'
            || str_contains($path, "\0") || str_contains($path, '\\')) {
            return false;
        }

        foreach (explode('/', $path) as $segment) {
            if ($segment === '' || $segment === '.' || $segment === '..') {
                return false;
            }
        }

        return true;
    }

    /**
     * Compare a tree on disk with the manifest. Symlinks are never followed.
     *
     * Paths under $linked are what the deploy replaces with links to shared
     * copies (storage, the .env, the shared paths): skipped entirely. Every
     * other file the manifest lists is always checked, wherever it is. Paths
     * under $generated only excuse what the manifest does not list — files
     * and links the node writes itself (bootstrap/cache, public/storage) —
     * so no ignore list can hide a change to a file CI signed.
     *
     * @param  list<string>  $linked  path prefixes
     * @param  list<string>  $generated  path prefixes
     * @return array{modified: list<string>, missing: list<string>, unlisted: list<string>, links: list<string>}
     */
    public function verifyTree(string $root, array $linked = [], array $generated = []): array
    {
        $isLinked = fn (string $path): bool => self::under($path, $linked);
        $isGenerated = fn (string $path): bool => self::under($path, $generated);

        $found = [];
        $links = [];
        $this->walk($root, '', $isLinked, $found, $links);

        $modified = [];
        $missing = [];
        foreach ($this->files as $path => [$sha, $size]) {
            $path = (string) $path;
            if ($isLinked($path)) {
                continue;
            }
            if (! isset($found[$path])) {
                $missing[] = $path;

                continue;
            }
            if ($found[$path] !== $size || hash_file('sha256', $root.'/'.$path) !== $sha) {
                $modified[] = $path;
            }
        }

        $unlisted = [];
        foreach (array_keys($found) as $path) {
            $path = (string) $path;
            if (! isset($this->files[$path]) && ! $isGenerated($path)) {
                $unlisted[] = $path;
            }
        }
        sort($unlisted, SORT_STRING);

        $links = array_values(array_filter($links, fn (string $path) => ! $isGenerated($path)));

        return ['modified' => $modified, 'missing' => $missing, 'unlisted' => $unlisted, 'links' => $links];
    }

    /**
     * @param  list<string>  $prefixes
     */
    public static function under(string $path, array $prefixes): bool
    {
        foreach ($prefixes as $prefix) {
            $prefix = trim(str_replace('\\', '/', (string) $prefix), '/');
            if ($prefix !== '' && ($path === $prefix || str_starts_with($path, $prefix.'/'))) {
                return true;
            }
        }

        return false;
    }

    /**
     * @param  \Closure(string): bool  $ignored
     * @param  array<string, int>  $found  path => size
     * @param  list<string>  $links
     */
    private function walk(string $root, string $relative, \Closure $ignored, array &$found, array &$links): void
    {
        $dir = $relative === '' ? $root : $root.'/'.$relative;
        $names = @scandir($dir, SCANDIR_SORT_ASCENDING);
        if ($names === false) {
            return;
        }

        foreach ($names as $name) {
            if ($name === '.' || $name === '..') {
                continue;
            }
            $path = $relative === '' ? $name : $relative.'/'.$name;
            if ($ignored($path)) {
                continue;
            }
            $absolute = $root.'/'.$path;
            if (is_link($absolute)) {
                $links[] = $path;
            } elseif (is_dir($absolute)) {
                $this->walk($root, $path, $ignored, $found, $links);
            } elseif (is_file($absolute)) {
                $found[$path] = (int) filesize($absolute);
            }
        }
    }
}

// — Pointer.php

/**
 * What a deploy ref points at in the store: one release, by commit and by
 * the hash of its manifest, with a sequence that only ever rises (a node
 * refuses an older pointer put back), the environment it belongs to (a
 * staging pointer copied into production's bucket verifies but is refused),
 * and the release before it, which is all a fresh node may fall back to.
 */
final class Pointer
{
    public const MAX_FUTURE_SECONDS = 86400;

    /**
     * @param  array{sha: string, manifest_sha256: string}|null  $previous
     */
    public function __construct(
        public readonly string $ref,
        public readonly string $sha,
        public readonly string $manifestSha256,
        public readonly int $sequence,
        public readonly string $publishedAt,
        public readonly ?array $previous,
        public readonly string $by,
        public readonly string $environment,
        public readonly string $slipstream,
        public readonly string $keyId,
    ) {}

    /**
     * @param  array<string, mixed>  $payload
     *
     * @throws ArtifactRefused when the payload is not a pointer
     */
    public static function fromPayload(array $payload, string $keyId): self
    {
        $refuse = fn (string $why) => throw new ArtifactRefused('pointer', 'the pointer is malformed: '.$why);

        $ref = $payload['ref'] ?? null;
        if (! is_string($ref) || preg_match('#^refs/(heads|tags)/[^\s]+$#', $ref) !== 1) {
            $refuse('ref');
        }
        $sha = $payload['sha'] ?? null;
        if (! is_string($sha) || preg_match('/^[0-9a-f]{40}$/', $sha) !== 1) {
            $refuse('sha');
        }
        $manifest = $payload['manifest_sha256'] ?? null;
        if (! is_string($manifest) || preg_match('/^[0-9a-f]{64}$/', $manifest) !== 1) {
            $refuse('manifest_sha256');
        }
        $sequence = $payload['sequence'] ?? null;
        if (! is_int($sequence) || $sequence < 1) {
            $refuse('sequence');
        }
        $publishedAt = $payload['published_at'] ?? null;
        if (! is_string($publishedAt) || $publishedAt === '' || strlen($publishedAt) > 64) {
            $refuse('published_at');
        }
        $environment = $payload['environment'] ?? null;
        if (! is_string($environment) || preg_match('/^[A-Za-z0-9._-]{1,64}$/', $environment) !== 1) {
            $refuse('environment');
        }
        $by = $payload['by'] ?? null;
        if (! is_string($by) || strlen($by) > 255) {
            $refuse('by');
        }
        $slipstream = $payload['slipstream'] ?? null;
        if (! is_string($slipstream) || strlen($slipstream) > 64) {
            $refuse('slipstream');
        }

        $previous = $payload['previous'] ?? null;
        if ($previous !== null) {
            if (! is_array($previous)
                || ! is_string($previous['sha'] ?? null) || preg_match('/^[0-9a-f]{40}$/', $previous['sha']) !== 1
                || ! is_string($previous['manifest_sha256'] ?? null) || preg_match('/^[0-9a-f]{64}$/', $previous['manifest_sha256']) !== 1) {
                $refuse('previous');
            }
            $previous = ['sha' => $previous['sha'], 'manifest_sha256' => $previous['manifest_sha256']];
        }

        return new self($ref, $sha, $manifest, $sequence, $publishedAt, $previous, $by, $environment, $slipstream, $keyId);
    }

    /**
     * @return array<string, mixed>
     */
    public function toPayload(): array
    {
        return [
            'by' => $this->by,
            'environment' => $this->environment,
            'manifest_sha256' => $this->manifestSha256,
            'previous' => $this->previous,
            'published_at' => $this->publishedAt,
            'ref' => $this->ref,
            'sequence' => $this->sequence,
            'sha' => $this->sha,
            'slipstream' => $this->slipstream,
        ];
    }

    public function short(): string
    {
        return substr($this->sha, 0, 7);
    }
}

// — ReleaseBuilder.php

/**
 * The manifest and statement for an archive, derived from the archive's own
 * bytes. The job that signs builds the manifest itself rather than trust the
 * one the build job wrote: a compromised build can only alter what the
 * tarball holds, never claim files it does not.
 */
final class ReleaseBuilder
{
    /**
     * @param  array{slipstream: string, environment: string, sha: string, ref: string, built_at: string, php: string, generated: list<string>}  $meta
     * @param  array{max_unpacked_bytes?: int, max_entries?: int}  $limits
     * @param  (\Closure(string, array<string, array{0: string, 1: int}>): void)|null  $inspect  sees the unpacked tree before it is removed; throws to refuse
     */
    public static function manifestFromArchive(string $tarGz, array $meta, array $limits = [], ?\Closure $inspect = null): Manifest
    {
        $scratch = self::scratchDirectory();

        try {
            $files = TarReader::extract($tarGz, $scratch, $limits);
            if ($inspect !== null) {
                $inspect($scratch, $files);
            }
        } finally {
            self::removeTree($scratch);
        }

        ksort($files, SORT_STRING);
        $unpacked = 0;
        foreach ($files as [, $size]) {
            $unpacked += $size;
        }

        return new Manifest(
            $meta['slipstream'],
            $meta['environment'],
            $meta['sha'],
            $meta['ref'],
            $meta['built_at'],
            $meta['php'],
            basename($tarGz),
            hash_file('sha256', $tarGz),
            (int) filesize($tarGz),
            $unpacked,
            self::countEntries($files),
            $files,
            array_values($meta['generated']),
        );
    }

    /**
     * What publish runs on the archive it is about to sign: the same rules
     * the packager applies, now on bytes the build job cannot talk its way
     * around.
     *
     * @param  list<string>  $allow  paths allowed to carry key material
     * @return \Closure(string, array<string, array{0: string, 1: int}>): void
     */
    public static function inspector(array $allow = []): \Closure
    {
        return function (string $root, array $files) use ($allow): void {
            $problems = ReleaseRules::problems($root, array_map('strval', array_keys($files)), $allow);
            if ($problems !== []) {
                throw new \RuntimeException('Refusing to publish: '.implode('; ', array_slice($problems, 0, 10))
                    .(count($problems) > 10 ? '; and '.(count($problems) - 10).' more' : '')
                    .'. Leave them out of the build (or name a path that may carry a key with --allow).');
            }
        };
    }

    /**
     * Everything a node will check about these bytes, checked before they
     * leave CI: the manifest parses as a node parses it, and both envelopes
     * verify under the keys the nodes hold. A KMS alias pointing at a key no
     * node trusts is found here, not by every node refusing the pointer.
     *
     * @throws \RuntimeException
     */
    public static function selfCheck(?string $manifestJson, ?string $statementEnvelope, ?string $pointerEnvelope, Keys $nodeKeys): void
    {
        if ($nodeKeys->count() === 0) {
            throw new \RuntimeException('No node keys to check against: pass --keys with the nodes\' SLIPSTREAM_RELEASE_PUBLIC_KEYS.');
        }

        if ($manifestJson !== null) {
            try {
                Manifest::fromJson($manifestJson);
            } catch (ArtifactRefused $e) {
                throw new \RuntimeException('Nodes would refuse this manifest: '.$e->reason);
            }
        }

        foreach ([[Envelope::DOMAIN_MANIFEST, $statementEnvelope, 'statement'], [Envelope::DOMAIN_POINTER, $pointerEnvelope, 'pointer']] as [$domain, $envelope, $what]) {
            if ($envelope === null) {
                continue;
            }
            try {
                Envelope::verify($envelope, $domain, $nodeKeys);
            } catch (SignatureException|ArtifactRefused $e) {
                throw new \RuntimeException("Nodes would refuse the {$what}: ".$e->getMessage().'. Is the signing key in the nodes\' SLIPSTREAM_RELEASE_PUBLIC_KEYS?');
            }
        }
    }

    /**
     * The statement that manifest.sig signs, for a manifest's exact bytes.
     */
    public static function statementFor(Manifest $manifest, string $manifestJson, string $environment): Statement
    {
        return new Statement(
            $manifest->sha,
            hash('sha256', $manifestJson),
            strlen($manifestJson),
            $manifest->archiveSha256,
            $manifest->ref,
            $environment,
            '',
        );
    }

    /**
     * Files plus the directory entries the writer emits for them.
     *
     * @param  array<string, array{0: string, 1: int}>  $files
     */
    private static function countEntries(array $files): int
    {
        $directories = [];
        foreach (array_keys($files) as $file) {
            $parts = explode('/', $file);
            array_pop($parts);
            for ($i = 1; $i <= count($parts); $i++) {
                $directories[implode('/', array_slice($parts, 0, $i))] = true;
            }
        }

        return count($files) + count($directories);
    }

    private static function scratchDirectory(): string
    {
        $dir = sys_get_temp_dir().DIRECTORY_SEPARATOR.'slipstream-release-'.bin2hex(random_bytes(6));
        if (! @mkdir($dir, 0700, true)) {
            throw new \RuntimeException("Cannot create {$dir}.");
        }

        return $dir;
    }

    private static function removeTree(string $path): void
    {
        if (is_link($path) || is_file($path)) {
            @unlink($path);

            return;
        }
        if (! is_dir($path)) {
            return;
        }
        foreach (scandir($path) ?: [] as $name) {
            if ($name !== '.' && $name !== '..') {
                self::removeTree($path.DIRECTORY_SEPARATOR.$name);
            }
        }
        @rmdir($path);
    }
}

// — ReleaseRules.php

/**
 * What a release must never carry, wherever it sits in the tree: VCS and
 * dependency directories, environment and credential files, local
 * databases, private keys. The packager leaves the names out; publish
 * applies the same rules to the archive itself, because the build job that
 * produced it is the untrusted side and Object Lock makes whatever reaches
 * the bucket permanent.
 */
final class ReleaseRules
{
    /** Directory names never shipped, at any depth. */
    public const NEVER_SHIP_DIRECTORIES = ['.git', 'node_modules'];

    /** File names never shipped, at any depth. */
    public const NEVER_SHIP_FILES = ['auth.json', '.envrc', '.npmrc', '.sentryclirc'];

    /** Key-store extensions refused outside vendor/. */
    public const KEY_STORES = ['p12', 'pfx', 'jks', 'keystore'];

    /** Files larger than this are not read for key material. */
    public const SCAN_LIMIT = 1048576;

    /**
     * Whether a path, or any directory on the way to it, must never ship.
     */
    public static function neverShips(string $path): bool
    {
        $segments = explode('/', trim(str_replace('\\', '/', $path), '/'));
        $last = count($segments) - 1;

        foreach ($segments as $i => $segment) {
            if (in_array($segment, self::NEVER_SHIP_DIRECTORIES, true)) {
                return true;
            }
            if ($i === $last && self::neverShipsName($segment, $path)) {
                return true;
            }
            // Name rules apply to directories on the way too (.env.d, …).
            if ($i < $last && (str_starts_with($segment, '.env') && $segment !== '.env.example')) {
                return true;
            }
        }

        return false;
    }

    /**
     * Why a file must not ship, judged by what it holds: a private key, or
     * a key store. Null when it may. Vendor code and allowed paths pass;
     * public certificates (a CA bundle) are fine.
     *
     * @param  list<string>  $allow  paths or path prefixes allowed to carry key material
     */
    public static function secretProblem(string $path, ?string $contents, array $allow = []): ?string
    {
        $path = trim(str_replace('\\', '/', $path), '/');
        if (str_starts_with($path, 'vendor/') || Manifest::under($path, $allow)) {
            return null;
        }

        if (in_array(strtolower(pathinfo($path, PATHINFO_EXTENSION)), self::KEY_STORES, true)) {
            return "{$path} is a key store";
        }
        if ($contents !== null && preg_match('/-----BEGIN (?:[A-Z0-9]+ )*PRIVATE KEY(?: BLOCK)?-----/', $contents) === 1) {
            return "{$path} holds a private key";
        }

        return null;
    }

    /**
     * Every problem with a tree on disk, for the files given: names that
     * never ship and key material.
     *
     * @param  list<string>  $paths  release-relative files
     * @param  list<string>  $allow
     * @return list<string>
     */
    public static function problems(string $root, array $paths, array $allow = []): array
    {
        $problems = [];

        foreach ($paths as $path) {
            $path = (string) $path;
            if (self::neverShips($path)) {
                $problems[] = "{$path} must never ship";

                continue;
            }

            $file = $root.'/'.$path;
            $contents = null;
            if (! str_starts_with($path, 'vendor/') && is_file($file) && (int) filesize($file) <= self::SCAN_LIMIT) {
                $contents = (string) @file_get_contents($file);
            }
            if (($problem = self::secretProblem($path, $contents, $allow)) !== null) {
                $problems[] = $problem;
            }
        }

        return $problems;
    }

    private static function neverShipsName(string $name, string $path): bool
    {
        if (in_array($name, self::NEVER_SHIP_FILES, true)) {
            return true;
        }
        if (str_starts_with($name, '.env') && $name !== '.env.example') {
            return true;
        }
        if (str_starts_with($name, '.yarnrc')) {
            return true;
        }

        return ! str_starts_with(ltrim($path, '/'), 'vendor/') && preg_match('/\.sqlite3?$/i', $name) === 1;
    }
}

// — SignatureException.php

/**
 * An envelope that does not verify, with the one reason it does not.
 */
final class SignatureException extends \RuntimeException {}

// — Signers.php

/**
 * The signer a key spec names: sodium:<base64>, file:<path>, or kms:<key>.
 */
final class Signers
{
    public static function fromSpec(string $spec, ?string $keyId = null): Signer
    {
        $spec = trim($spec);

        return match (true) {
            str_starts_with($spec, 'kms:') => KmsSigner::fromSpec($spec, $keyId),
            str_starts_with($spec, 'sodium:'), str_starts_with($spec, 'file:') => SodiumSigner::fromSpec($spec, $keyId),
            default => throw new \InvalidArgumentException('A signing key is sodium:<base64 secret>, file:<path>, or kms:<key id, ARN or alias>.'),
        };
    }
}

// — SodiumSigner.php

/**
 * Signs with an Ed25519 secret key held locally: `sodium:<base64 of the
 * 64-byte secret key>` or `file:<path>` holding that base64.
 */
final class SodiumSigner implements Signer
{
    public function __construct(private string $secretKey, private ?string $keyId = null)
    {
        if (strlen($secretKey) !== SODIUM_CRYPTO_SIGN_SECRETKEYBYTES) {
            throw new \InvalidArgumentException('An Ed25519 secret key is 64 bytes.');
        }
    }

    public static function fromSpec(string $spec, ?string $keyId = null): self
    {
        $spec = trim($spec);

        if (str_starts_with($spec, 'file:')) {
            $path = substr($spec, 5);
            $contents = is_file($path) ? @file_get_contents($path) : false;
            if ($contents === false) {
                throw new \InvalidArgumentException("The signing key file {$path} cannot be read.");
            }
            $encoded = trim($contents);
            $encoded = str_starts_with($encoded, 'sodium:') ? substr($encoded, 7) : $encoded;
        } elseif (str_starts_with($spec, 'sodium:')) {
            $encoded = substr($spec, 7);
        } else {
            throw new \InvalidArgumentException('A sodium signing key is sodium:<base64> or file:<path>.');
        }

        $raw = base64_decode(trim($encoded), true);
        if ($raw === false) {
            throw new \InvalidArgumentException('The signing key is not base64.');
        }

        return new self($raw, $keyId);
    }

    /**
     * A fresh key pair, both halves base64, with the id nodes would derive.
     *
     * @return array{secret: string, public: string, key_id: string}
     */
    public static function generate(): array
    {
        $pair = sodium_crypto_sign_keypair();
        $public = sodium_crypto_sign_publickey($pair);

        return [
            'secret' => base64_encode(sodium_crypto_sign_secretkey($pair)),
            'public' => base64_encode($public),
            'key_id' => Keys::deriveId($public),
        ];
    }

    public function sign(string $message): string
    {
        return sodium_crypto_sign_detached($message, $this->secretKey);
    }

    public function publicKey(): string
    {
        return sodium_crypto_sign_publickey_from_secretkey($this->secretKey);
    }

    public function keyId(): string
    {
        return $this->keyId ??= Keys::deriveId($this->publicKey());
    }
}

// — Statement.php

/**
 * What manifest.sig signs: not the manifest (it can run to megabytes, KMS
 * signs 4 KB) but its hash and size, the archive's hash, the commit, the ref
 * it was built for and the environment it belongs to.
 */
final class Statement
{
    public function __construct(
        public readonly string $sha,
        public readonly string $manifestSha256,
        public readonly int $manifestSize,
        public readonly string $archiveSha256,
        public readonly string $ref,
        public readonly string $environment,
        public readonly string $keyId,
    ) {}

    /**
     * @param  array<string, mixed>  $payload
     *
     * @throws ArtifactRefused when the payload is not a statement
     */
    public static function fromPayload(array $payload, string $keyId): self
    {
        $refuse = fn (string $why) => throw new ArtifactRefused('statement', 'the manifest statement is malformed: '.$why);

        foreach (['sha' => 40, 'manifest_sha256' => 64, 'archive_sha256' => 64] as $field => $length) {
            if (! is_string($payload[$field] ?? null) || preg_match('/^[0-9a-f]{'.$length.'}$/', $payload[$field]) !== 1) {
                $refuse($field);
            }
        }
        if (! is_int($payload['manifest_size'] ?? null) || $payload['manifest_size'] < 1) {
            $refuse('manifest_size');
        }
        if (! is_string($payload['ref'] ?? null) || preg_match('#^refs/(heads|tags)/[^\s]+$#', $payload['ref']) !== 1) {
            $refuse('ref');
        }
        if (! is_string($payload['environment'] ?? null) || preg_match('/^[A-Za-z0-9._-]{1,64}$/', $payload['environment']) !== 1) {
            $refuse('environment');
        }

        return new self(
            $payload['sha'],
            $payload['manifest_sha256'],
            $payload['manifest_size'],
            $payload['archive_sha256'],
            $payload['ref'],
            $payload['environment'],
            $keyId,
        );
    }

    /**
     * @return array<string, mixed>
     */
    public function toPayload(): array
    {
        return [
            'archive_sha256' => $this->archiveSha256,
            'environment' => $this->environment,
            'manifest_sha256' => $this->manifestSha256,
            'manifest_size' => $this->manifestSize,
            'ref' => $this->ref,
            'sha' => $this->sha,
        ];
    }
}

// — TarReader.php

/**
 * Unpacks a release tarball the way a node must: regular files and
 * directories only, every name a release-relative path, a byte and entry
 * budget enforced as it goes, nothing written through a symlink, nothing
 * overwritten, and every file hashed while it is written and compared with
 * the manifest. Anything else refuses the archive.
 *
 * It reads exactly what TarWriter writes and nothing looser: POSIX ustar
 * headers, size-0 directory entries, GNU long names, two zero blocks at the
 * end. Where other tar readers disagree with each other (a directory with a
 * size, a file named like a directory, a GNU header's prefix field), the
 * archive is refused rather than read one way here and another in review.
 */
final class TarReader
{
    public const BLOCK = 512;

    /** What a long name and a header may add to an entry, at most. */
    public const ENTRY_OVERHEAD = 6144;

    /** The end marker, plus the zero padding a record may carry after it. */
    public const TAIL = 11264;

    /**
     * @param  array{max_unpacked_bytes?: int, max_entries?: int}  $limits
     * @param  array<string, array{0: string, 1: int}>|null  $expected  the manifest's files; when given, every file must be in it and match, and all of them must be present
     * @return array<string, array{0: string, 1: int}>  the files extracted, release-relative, each with its SHA-256 and size, in archive order
     *
     * @throws ArtifactRefused  for an archive the node will not take
     * @throws \RuntimeException  when the disk is the problem (a write that does not complete)
     */
    public static function extract(string $tarGz, string $into, array $limits = [], ?array $expected = null): array
    {
        $maxBytes = $limits['max_unpacked_bytes'] ?? PHP_INT_MAX;
        $maxEntries = $limits['max_entries'] ?? PHP_INT_MAX;

        $gz = gzopen($tarGz, 'rb');
        if ($gz === false) {
            throw new ArtifactRefused('archive', 'the archive cannot be opened');
        }
        $stream = new TarStream($gz, self::readCap($maxBytes, $maxEntries));

        $extracted = [];
        $bytes = 0;
        $entries = 0;
        $longName = null;
        $created = [];

        try {
            while (true) {
                $header = $stream->read(self::BLOCK);
                if (strlen($header) !== self::BLOCK) {
                    throw new ArtifactRefused('archive', $header === '' ? 'the archive ends without an end-of-archive marker' : 'the archive is truncated');
                }
                if ($header === str_repeat("\0", self::BLOCK)) {
                    if ($longName !== null) {
                        throw new ArtifactRefused('archive', 'a long-name entry is not followed by the entry it names');
                    }
                    if ($stream->readExactly(self::BLOCK) !== str_repeat("\0", self::BLOCK)) {
                        throw new ArtifactRefused('archive', 'the archive ends without an end-of-archive marker');
                    }
                    self::checkTail($stream);
                    break;
                }

                $fields = self::parseHeader($header);
                $type = $fields['type'];
                $size = $fields['size'];

                if ($type === 'L') {
                    if ($longName !== null) {
                        throw new ArtifactRefused('archive', 'two long-name entries in a row');
                    }
                    if ($size < 1 || $size > Manifest::MAX_PATH + 1) {
                        throw new ArtifactRefused('archive', 'a long-name entry of an impossible size');
                    }
                    $longName = rtrim($stream->readExactly($size), "\0");
                    $stream->skip(self::padding($size));

                    continue;
                }

                $name = $longName ?? $fields['name'];
                $longName = null;

                if (++$entries > $maxEntries) {
                    throw new ArtifactRefused('archive', "more than {$maxEntries} entries");
                }

                if ($type !== '0' && $type !== "\0" && $type !== '5') {
                    throw new ArtifactRefused('archive', 'refusing '.self::describeType($type).' entry "'.self::printable($name).'"');
                }
                if ($type === '5' && $size !== 0) {
                    throw new ArtifactRefused('archive', 'refusing the directory entry "'.self::printable($name).'", which claims '.$size.' bytes of data');
                }
                if ($type !== '5' && str_ends_with($name, '/')) {
                    throw new ArtifactRefused('archive', 'refusing the file entry "'.self::printable($name).'", which is named like a directory');
                }

                $name = rtrim($name, '/');
                if (! Manifest::validPath($name)) {
                    throw new ArtifactRefused('archive', 'refusing entry name "'.self::printable($name).'"');
                }

                if ($type === '5') {
                    self::ensureDirectory($into, $name, $created);

                    continue;
                }

                $bytes += $size;
                if ($bytes > $maxBytes) {
                    throw new ArtifactRefused('archive', "unpacked size exceeds {$maxBytes} bytes");
                }
                if ($expected !== null && ! isset($expected[$name])) {
                    throw new ArtifactRefused('files', 'the archive carries a file the manifest does not list: '.self::printable($name));
                }
                if ($expected !== null && $expected[$name][1] !== $size) {
                    throw new ArtifactRefused('files', self::printable($name).' is '.$size.' bytes; the manifest says '.$expected[$name][1]);
                }

                $parent = dirname($name);
                if ($parent !== '.') {
                    self::ensureDirectory($into, $parent, $created);
                }

                $target = $into.'/'.$name;
                if (is_link($target) || file_exists($target)) {
                    throw new ArtifactRefused('archive', 'the archive lists '.self::printable($name).' twice');
                }

                $digest = self::writeFile($stream, $target, $name, $size);
                $stream->skip(self::padding($size));
                @chmod($target, ($fields['mode'] & 0100) ? 0755 : 0644);

                if ($expected !== null && $expected[$name][0] !== $digest) {
                    throw new ArtifactRefused('files', self::printable($name).' does not match the manifest', null, ['expected' => $expected[$name][0], 'actual' => $digest]);
                }

                $extracted[$name] = [$digest, $size];
            }
        } finally {
            gzclose($gz);
        }

        if ($expected !== null) {
            $missing = array_diff(array_map('strval', array_keys($expected)), array_map('strval', array_keys($extracted)));
            if ($missing !== []) {
                throw new ArtifactRefused('files', count($missing).' file(s) the manifest lists are not in the archive: '.implode(', ', array_slice(array_values($missing), 0, 5)));
            }
        }

        return $extracted;
    }

    /**
     * How many decompressed bytes an archive within these limits can need.
     */
    public static function readCap(int $maxBytes, int $maxEntries): int
    {
        $cap = (float) $maxBytes + (float) $maxEntries * self::ENTRY_OVERHEAD + self::TAIL;

        return $cap >= PHP_INT_MAX ? PHP_INT_MAX : (int) $cap;
    }

    /**
     * Write one entry's data, hashing what goes to disk. A write that does
     * not complete (a full disk, a quota, a file-size limit) stops the
     * extract: the hash would otherwise vouch for bytes that never landed.
     */
    private static function writeFile(TarStream $stream, string $target, string $name, int $size): string
    {
        $out = @fopen($target, 'xb');
        if ($out === false) {
            throw new ArtifactRefused('archive', 'cannot write '.self::printable($name));
        }

        $hash = hash_init('sha256');
        $remaining = $size;
        try {
            while ($remaining > 0) {
                $chunk = $stream->read(min(65536, $remaining));
                if ($chunk === '') {
                    throw new ArtifactRefused('archive', 'the archive is truncated inside '.self::printable($name));
                }
                hash_update($hash, $chunk);
                self::writeAll($out, $chunk, $name);
                $remaining -= strlen($chunk);
            }
        } catch (\Throwable $e) {
            @fclose($out);

            throw $e;
        }

        if (! fclose($out)) {
            throw new \RuntimeException('Cannot finish writing '.self::printable($name).'; the disk may be full.');
        }
        clearstatcache(true, $target);
        $onDisk = @filesize($target);
        if ($onDisk !== $size) {
            throw new \RuntimeException(self::printable($name).' is '.var_export($onDisk, true)." bytes on disk, not {$size}: the write did not complete (is the disk full?).");
        }

        return hash_final($hash);
    }

    /**
     * @param  resource  $out
     */
    private static function writeAll($out, string $data, string $name): void
    {
        $offset = 0;
        $length = strlen($data);
        while ($offset < $length) {
            $written = @fwrite($out, $offset === 0 ? $data : substr($data, $offset));
            if ($written === false || $written === 0) {
                throw new \RuntimeException('Cannot write '.self::printable($name).'; the disk may be full.');
            }
            $offset += $written;
        }
    }

    /**
     * After the end marker: zero padding up to a record, then nothing. The
     * rest is never inflated to look for more.
     */
    private static function checkTail(TarStream $stream): void
    {
        $padding = $stream->read(self::TAIL - 2 * self::BLOCK);
        if (trim($padding, "\0") !== '') {
            throw new ArtifactRefused('archive', 'data follows the end-of-archive marker');
        }
        if (strlen($padding) === self::TAIL - 2 * self::BLOCK && ! $stream->atEnd()) {
            throw new ArtifactRefused('archive', 'data follows the end-of-archive marker');
        }
    }

    private static function padding(int $size): int
    {
        return $size % self::BLOCK === 0 ? 0 : self::BLOCK - ($size % self::BLOCK);
    }

    /**
     * @return array{name: string, mode: int, size: int, type: string}
     */
    private static function parseHeader(string $header): array
    {
        // POSIX ustar only, as TarWriter writes it. A GNU header ("ustar  ")
        // uses the prefix field for other things, and readers disagree.
        if (substr($header, 257, 6) !== "ustar\0" || substr($header, 263, 2) !== '00') {
            throw new ArtifactRefused('archive', 'not a POSIX ustar header');
        }

        $sum = 0;
        for ($i = 0; $i < self::BLOCK; $i++) {
            $sum += ($i >= 148 && $i < 156) ? 32 : ord($header[$i]);
        }
        if ($sum !== self::octal(substr($header, 148, 8))) {
            throw new ArtifactRefused('archive', 'a header checksum does not match');
        }

        $name = rtrim(substr($header, 0, 100), "\0");
        $prefix = rtrim(substr($header, 345, 155), "\0");

        return [
            'name' => $prefix !== '' ? $prefix.'/'.$name : $name,
            'mode' => self::octal(substr($header, 100, 8)),
            'size' => self::octal(substr($header, 124, 12)),
            'type' => $header[156],
        ];
    }

    private static function octal(string $field): int
    {
        $field = trim($field, "\0 ");

        if ($field !== '' && preg_match('/^[0-7]+$/', $field) !== 1) {
            throw new ArtifactRefused('archive', 'a header field is not octal');
        }

        return $field === '' ? 0 : (int) octdec($field);
    }

    /**
     * Create a directory one component at a time, never through a symlink.
     *
     * @param  array<string, bool>  $created
     */
    private static function ensureDirectory(string $into, string $relative, array &$created): void
    {
        $path = $into;
        $walked = '';

        foreach (explode('/', $relative) as $segment) {
            $walked = $walked === '' ? $segment : $walked.'/'.$segment;
            $path .= '/'.$segment;

            if (isset($created[$walked])) {
                continue;
            }
            if (is_link($path)) {
                throw new ArtifactRefused('archive', 'refusing to write through the symlink '.self::printable($walked));
            }
            if (file_exists($path)) {
                if (! is_dir($path)) {
                    throw new ArtifactRefused('archive', self::printable($walked).' is in the way of a directory');
                }
            } elseif (! @mkdir($path, 0755)) {
                throw new ArtifactRefused('archive', 'cannot create the directory '.self::printable($walked));
            }
            @chmod($path, 0755);
            $created[$walked] = true;
        }
    }

    private static function describeType(string $type): string
    {
        return match ($type) {
            '1' => 'a hard link',
            '2' => 'a symlink',
            '3', '4' => 'a device',
            '6' => 'a FIFO',
            '7' => 'a contiguous-file',
            'x', 'g' => 'a pax header',
            default => 'a type '.bin2hex($type),
        };
    }

    private static function printable(string $name): string
    {
        $clean = preg_replace('/[^\x20-\x7e]/', '?', $name) ?? '';

        return strlen($clean) > 200 ? substr($clean, 0, 199).'...' : $clean;
    }
}

// — TarStream.php

/**
 * The decompressed bytes of a release tarball, counted. Every byte the
 * reader takes — headers, file data, padding, long names, what follows the
 * end marker — goes through here, so a small archive cannot be made to
 * inflate past what the release and its framing need.
 */
final class TarStream
{
    private int $read = 0;

    /**
     * @param  resource  $gz
     */
    public function __construct(private $gz, private int $cap) {}

    /**
     * Up to $size bytes; fewer only at the end of the stream.
     */
    public function read(int $size): string
    {
        $data = '';
        while (strlen($data) < $size) {
            $chunk = gzread($this->gz, min(65536, $size - strlen($data)));
            if ($chunk === false || $chunk === '') {
                break;
            }
            $this->count(strlen($chunk));
            $data .= $chunk;
        }

        return $data;
    }

    /**
     * Exactly $size bytes, or the archive is truncated.
     */
    public function readExactly(int $size): string
    {
        $data = $this->read($size);
        if (strlen($data) !== $size) {
            throw new ArtifactRefused('archive', 'the archive is truncated');
        }

        return $data;
    }

    public function skip(int $size): void
    {
        while ($size > 0) {
            $chunk = $this->read(min(65536, $size));
            if ($chunk === '') {
                throw new ArtifactRefused('archive', 'the archive is truncated');
            }
            $size -= strlen($chunk);
        }
    }

    public function atEnd(): bool
    {
        return $this->read(1) === '';
    }

    private function count(int $bytes): void
    {
        $this->read += $bytes;
        if ($this->read > $this->cap) {
            throw new ArtifactRefused('archive', "the archive inflates past {$this->cap} bytes, more than the release and its headers need");
        }
    }
}

// — TarWriter.php

/**
 * Writes a release tarball: ustar, gzip, and deterministic — entries sorted,
 * every mtime 0, every owner 0, modes 0644 or 0755 — so the same tree always
 * gives the same bytes and the archive's hash means something. Regular files
 * and directories only: a symlink in the tree is a build error, named.
 */
final class TarWriter
{
    public const BLOCK = 512;

    /** ustar's limit; a larger file needs a format nodes refuse. */
    public const MAX_FILE = 8589934591;

    /**
     * @param  list<string>  $files  release-relative paths of regular files, forward slashes
     * @return array{sha256: string, size: int, unpacked_bytes: int, entries: int}
     */
    public static function create(string $tarGz, string $root, array $files): array
    {
        $files = array_values(array_unique($files));
        sort($files, SORT_STRING);

        $directories = [];
        foreach ($files as $file) {
            if (! Manifest::validPath($file)) {
                throw new \InvalidArgumentException("\"{$file}\" is not a release-relative path.");
            }
            $parts = explode('/', $file);
            array_pop($parts);
            for ($i = 1; $i <= count($parts); $i++) {
                $directories[implode('/', array_slice($parts, 0, $i))] = true;
            }
        }
        $directories = array_keys($directories);
        sort($directories, SORT_STRING);

        $gz = gzopen($tarGz, 'wb9');
        if ($gz === false) {
            throw new \RuntimeException("Cannot write {$tarGz}.");
        }

        $unpacked = 0;
        $entries = 0;

        try {
            foreach ($directories as $directory) {
                self::writeHeader($gz, $directory.'/', 0755, 0, '5');
                $entries++;
            }

            foreach ($files as $file) {
                $absolute = $root.'/'.$file;
                if (is_link($absolute)) {
                    throw new \RuntimeException("{$file} is a symlink; a release carries regular files only.");
                }
                if (! is_file($absolute)) {
                    throw new \RuntimeException("{$file} is not a regular file.");
                }
                $size = (int) filesize($absolute);
                if ($size > self::MAX_FILE) {
                    throw new \RuntimeException("{$file} is larger than a tar entry can be.");
                }

                $mode = (fileperms($absolute) & 0100) ? 0755 : 0644;
                self::writeHeader($gz, $file, $mode, $size, '0');

                $in = fopen($absolute, 'rb');
                if ($in === false) {
                    throw new \RuntimeException("Cannot read {$file}.");
                }
                $written = 0;
                while (! feof($in)) {
                    $chunk = fread($in, 65536);
                    if ($chunk === false) {
                        break;
                    }
                    gzwrite($gz, $chunk);
                    $written += strlen($chunk);
                }
                fclose($in);
                if ($written !== $size) {
                    throw new \RuntimeException("{$file} changed while being packed.");
                }
                self::pad($gz, $size);

                $unpacked += $size;
                $entries++;
            }

            gzwrite($gz, str_repeat("\0", self::BLOCK * 2));
        } finally {
            gzclose($gz);
        }

        return [
            'sha256' => hash_file('sha256', $tarGz),
            'size' => (int) filesize($tarGz),
            'unpacked_bytes' => $unpacked,
            'entries' => $entries,
        ];
    }

    /**
     * @param  resource  $gz
     */
    private static function writeHeader($gz, string $name, int $mode, int $size, string $type): void
    {
        [$short, $prefix] = self::split($name);

        if ($short === null) {
            // GNU long name: an 'L' entry carrying the path, then the real header.
            self::writeHeader($gz, '././@LongLink', 0, strlen($name) + 1, 'L');
            gzwrite($gz, $name."\0");
            self::pad($gz, strlen($name) + 1);
            $short = substr($name, 0, 100);
            $prefix = '';
        }

        $header = str_pad($short, 100, "\0")
            .sprintf("%07o\0", $mode)
            .sprintf("%07o\0", 0)
            .sprintf("%07o\0", 0)
            .sprintf("%011o\0", $size)
            .sprintf("%011o\0", 0)
            .'        '
            .$type
            .str_repeat("\0", 100)
            ."ustar\0"
            .'00'
            .str_repeat("\0", 32)
            .str_repeat("\0", 32)
            .sprintf("%07o\0", 0)
            .sprintf("%07o\0", 0)
            .str_pad($prefix, 155, "\0")
            .str_repeat("\0", 12);

        $sum = 0;
        for ($i = 0; $i < self::BLOCK; $i++) {
            $sum += ord($header[$i]);
        }
        $header = substr_replace($header, sprintf("%06o\0 ", $sum), 148, 8);

        gzwrite($gz, $header);
    }

    /**
     * Where ustar splits a long path into prefix and name, or [null, null]
     * when it cannot.
     *
     * @return array{0: ?string, 1: ?string}
     */
    private static function split(string $name): array
    {
        if (strlen($name) <= 100) {
            return [$name, ''];
        }

        $position = strlen($name);
        while (($position = strrpos(substr($name, 0, $position), '/')) !== false) {
            $prefix = substr($name, 0, $position);
            $rest = substr($name, $position + 1);
            if (strlen($prefix) <= 155 && strlen($rest) <= 100 && $rest !== '') {
                return [$rest, $prefix];
            }
            if ($position === 0) {
                break;
            }
        }

        return [null, null];
    }

    /**
     * @param  resource  $gz
     */
    private static function pad($gz, int $size): void
    {
        $remainder = $size % self::BLOCK;
        if ($remainder !== 0) {
            gzwrite($gz, str_repeat("\0", self::BLOCK - $remainder));
        }
    }
}

}

namespace {

// The main program of stubs/slipstream-release.php: the Core classes above,
// driven from the command line, with no framework and no Composer. CI signs
// and publishes with it (the job that holds the signing key runs nothing
// else), slipstream-bootstrap.sh verifies the first release with it on a node
// that has no Slipstream code yet, and a root timer checks the live release
// with it from outside the tree the deploy user can write.

use Slipstream\Release\Core\ArtifactRefused;
use Slipstream\Release\Core\Baseline;
use Slipstream\Release\Core\Envelope;
use Slipstream\Release\Core\Keys;
use Slipstream\Release\Core\KmsSigner;
use Slipstream\Release\Core\Manifest;
use Slipstream\Release\Core\Pointer;
use Slipstream\Release\Core\ReleaseBuilder;
use Slipstream\Release\Core\Signer;
use Slipstream\Release\Core\Signers;
use Slipstream\Release\Core\Statement;
use Slipstream\Release\Core\TarReader;

const SLIPSTREAM_RELEASE_USAGE = <<<'TXT'
slipstream-release.php — artifact releases without the framework

  verify-pointer  --ref=refs/heads/production --environment=production --keys=id:base64[,id:base64]|file:/abs/path
                  --pointer=<file> [--min-sequence=N]
                  Prints sha=, manifest_sha256=, sequence=, previous_sha=, previous_manifest_sha256=.

  verify-release  --sha=<40 hex> --ref=… --environment=… --keys=… --manifest=<file> --signature=<file>
                  --archive=<file> --extract-to=<empty dir> [--manifest-sha256=<hex>]
                  Verifies, unpacks, writes RELEASE_SHA and .slipstream/. Prints files=N.
                  On a refusal, removes what it unpacked.

  verify-tree     --release=<dir> --keys=… --environment=… [--shared=a,b] [--state-dir=<dir>] [--json]
                  The live release against its signed manifest and the cache hashes recorded at
                  deploy, from outside it: run it as root from a copy the deploy user cannot
                  write, with keys from a root-owned file. Exit 0 clean, 1 drift.

  publish         --archive=<file> --manifest=<build manifest> --ref=… --environment=…
                  --sha=<40 hex> (default GITHUB_SHA) --keys=<the nodes' keys>
                  --key=sodium:…|file:…|kms:… [--key-id=…] --store=s3://bucket/prefix|file:///dir
                  [--by=…] [--generated=a,b] [--allow=a,b] [--max-unpacked-bytes=N] [--max-entries=N]
                  Regenerates the manifest from the archive, checks it as a node would, signs,
                  uploads write-once, then moves the pointer only if no other publish did.

  rollback        --sha=… --ref=… --environment=… --keys=… --key=… [--key-id=…] --store=… [--by=…]
                  Points the ref at a release already in the store.

Exit 0 on success, 1 on a refusal, drift or error (the reason on stderr), 2 on usage.
TXT;

/**
 * @return array<string, string|true>
 */
function slipstream_release_options(array $args): array
{
    $options = [];
    foreach ($args as $arg) {
        if (! str_starts_with($arg, '--')) {
            slipstream_release_fail("unexpected argument {$arg}", 2);
        }
        [$name, $value] = array_pad(explode('=', substr($arg, 2), 2), 2, true);
        $options[$name] = $value;
    }

    return $options;
}

/**
 * @param  array<string, string|true>  $options
 */
function slipstream_release_need(array $options, string $name): string
{
    if (! isset($options[$name]) || $options[$name] === true || $options[$name] === '') {
        slipstream_release_fail("--{$name} is required", 2);
    }

    return (string) $options[$name];
}

/**
 * @param  array<string, string|true>  $options
 */
function slipstream_release_option(array $options, string $name): ?string
{
    return isset($options[$name]) && $options[$name] !== true && $options[$name] !== '' ? (string) $options[$name] : null;
}

/**
 * @param  array<string, string|true>  $options
 * @param  list<string>  $default
 * @return list<string>
 */
function slipstream_release_list(array $options, string $name, array $default): array
{
    if (! isset($options[$name]) || $options[$name] === true) {
        return $default;
    }

    return array_values(array_filter(array_map(fn (string $item) => trim($item, " \t/"), explode(',', (string) $options[$name])), fn (string $item) => $item !== ''));
}

function slipstream_release_fail(string $message, int $code = 1): never
{
    fwrite(STDERR, "slipstream-release: {$message}\n");
    exit($code);
}

function slipstream_release_say(string $line): void
{
    fwrite(STDOUT, $line."\n");
}

function slipstream_release_read(string $file, int $max): string
{
    if (! is_file($file)) {
        slipstream_release_fail("no such file: {$file}");
    }
    if (filesize($file) > $max) {
        slipstream_release_fail("{$file} exceeds {$max} bytes");
    }

    return (string) file_get_contents($file);
}

function slipstream_release_remove_tree(string $path): void
{
    if (is_link($path) || is_file($path)) {
        @unlink($path);

        return;
    }
    if (! is_dir($path)) {
        return;
    }
    foreach (scandir($path) ?: [] as $name) {
        if ($name !== '.' && $name !== '..') {
            slipstream_release_remove_tree($path.'/'.$name);
        }
    }
    @rmdir($path);
}

/**
 * A pointer that passes every check a node applies, or a refusal.
 */
function slipstream_release_pointer(string $envelope, string $ref, string $environment, Keys $keys, int $minSequence = 0): Pointer
{
    $verified = Envelope::verify($envelope, Envelope::DOMAIN_POINTER, $keys);
    $pointer = Pointer::fromPayload($verified['payload'], $verified['key_id']);

    if ($pointer->environment !== $environment) {
        throw new ArtifactRefused('pointer', "it is signed for environment \"{$pointer->environment}\"; this node is \"{$environment}\"");
    }
    if ($pointer->ref !== $ref) {
        throw new ArtifactRefused('pointer', "it names {$pointer->ref}, not {$ref}");
    }
    if ($pointer->sequence < $minSequence) {
        throw new ArtifactRefused('pointer', "sequence {$pointer->sequence} is below {$minSequence}, which this node already accepted");
    }
    if ($pointer->sequence > time() + Pointer::MAX_FUTURE_SECONDS) {
        throw new ArtifactRefused('pointer', "sequence {$pointer->sequence} is more than a day in the future");
    }

    return $pointer;
}

/**
 * @return array{0: string, 1: string}  bucket, key prefix ('' or 'prefix/')
 */
function slipstream_release_s3(string $store): array
{
    [$bucket, $prefix] = array_pad(explode('/', substr($store, 5), 2), 2, '');
    $prefix = trim($prefix, '/');
    if ($bucket === '') {
        slipstream_release_fail('--store must be s3://bucket/prefix or file:///dir', 2);
    }

    return [$bucket, $prefix === '' ? '' : $prefix.'/'];
}

function slipstream_release_file_path(string $store, string $key): string
{
    return rtrim(substr($store, 7), '/').'/'.$key;
}

function slipstream_release_is_conflict(\Throwable $e): bool
{
    return preg_match('/PreconditionFailed|ConditionalRequestConflict|\(412\)|\(409\)/i', $e->getMessage()) === 1;
}

/**
 * Download an object to a file. False when it is not there.
 *
 * @return string|false  the object's ETag (for file://, its content's SHA-1)
 */
function slipstream_release_store_fetch(string $store, string $key, string $to): string|false
{
    if (str_starts_with($store, 'file://')) {
        $path = slipstream_release_file_path($store, $key);
        if (! is_file($path)) {
            return false;
        }
        if (! copy($path, $to)) {
            throw new \RuntimeException("Cannot read {$path}.");
        }

        return (string) sha1_file($to);
    }
    if (str_starts_with($store, 's3://')) {
        [$bucket, $prefix] = slipstream_release_s3($store);
        try {
            $meta = json_decode(KmsSigner::cli(['aws', 's3api', 'get-object', '--bucket', $bucket, '--key', $prefix.$key, $to, '--output', 'json']), true);

            return is_array($meta) ? (string) ($meta['ETag'] ?? '') : '';
        } catch (\RuntimeException $e) {
            if (preg_match('/NoSuchKey|Not Found|\(404\)/i', $e->getMessage()) === 1) {
                return false;
            }
            throw $e;
        }
    }

    slipstream_release_fail('--store must be s3://bucket/prefix or file:///dir', 2);
}

/**
 * An object's contents and ETag, or [null, null] when it is not there.
 *
 * @return array{0: ?string, 1: ?string}
 */
function slipstream_release_store_get(string $store, string $key): array
{
    $tmp = (string) tempnam(sys_get_temp_dir(), 'ss-get-');
    try {
        $etag = slipstream_release_store_fetch($store, $key, $tmp);

        return $etag === false ? [null, null] : [(string) file_get_contents($tmp), $etag];
    } finally {
        @unlink($tmp);
    }
}

/**
 * Write-once. True when written; false when the very same bytes were
 * already there (a re-run of the publish job). Different bytes are refused:
 * a published release is never replaced.
 */
function slipstream_release_store_put_once(string $store, string $key, string $file): bool
{
    $refuse = fn () => new \RuntimeException("{$key} is already in the store with different content. A published release is never replaced: publish a new commit. (If an earlier publish of this commit stopped half-way, remove its releases/<sha>/ objects with the break-glass role first.)");

    if (str_starts_with($store, 'file://')) {
        $path = slipstream_release_file_path($store, $key);
        if (! is_dir(dirname($path)) && ! @mkdir(dirname($path), 0755, true)) {
            throw new \RuntimeException('Cannot create '.dirname($path).'.');
        }
        $out = @fopen($path, 'xb');
        if ($out === false) {
            if (is_file($path) && hash_file('sha256', $path) === hash_file('sha256', $file)) {
                return false;
            }
            throw is_file($path) ? $refuse() : new \RuntimeException("Cannot write {$path}.");
        }
        $in = fopen($file, 'rb');
        $copied = $in !== false ? stream_copy_to_stream($in, $out) : false;
        if ($in !== false) {
            fclose($in);
        }
        if (! fclose($out) || $copied !== filesize($file)) {
            @unlink($path);
            throw new \RuntimeException("Cannot write {$path}.");
        }

        return true;
    }
    if (str_starts_with($store, 's3://')) {
        [$bucket, $prefix] = slipstream_release_s3($store);
        try {
            KmsSigner::cli(['aws', 's3api', 'put-object', '--bucket', $bucket, '--key', $prefix.$key, '--body', $file, '--if-none-match', '*', '--output', 'json']);

            return true;
        } catch (\RuntimeException $e) {
            if (! slipstream_release_is_conflict($e)) {
                throw $e;
            }
        }

        $tmp = (string) tempnam(sys_get_temp_dir(), 'ss-cmp-');
        try {
            if (slipstream_release_store_fetch($store, $key, $tmp) !== false && hash_file('sha256', $tmp) === hash_file('sha256', $file)) {
                return false;
            }
        } finally {
            @unlink($tmp);
        }
        throw $refuse();
    }

    slipstream_release_fail('--store must be s3://bucket/prefix or file:///dir', 2);
}

/**
 * Write the pointer only if it is still what this publish read: If-Match on
 * the ETag it read, If-None-Match when there was none. Two publishes can
 * never both win, so two pointers never share a sequence.
 */
function slipstream_release_store_put_pointer(string $store, string $key, string $file, ?string $etag): void
{
    $moved = fn () => new \RuntimeException("Another publish moved {$key} while this one ran; nothing was pointed. Run the publish again.");

    if (str_starts_with($store, 'file://')) {
        $path = slipstream_release_file_path($store, $key);
        if (! is_dir(dirname($path)) && ! @mkdir(dirname($path), 0755, true)) {
            throw new \RuntimeException('Cannot create '.dirname($path).'.');
        }
        $lock = fopen($path.'.lock', 'c');
        if ($lock === false || ! flock($lock, LOCK_EX)) {
            throw new \RuntimeException("Cannot lock {$path}.");
        }
        try {
            $now = is_file($path) ? (string) sha1_file($path) : null;
            if ($now !== $etag) {
                throw $moved();
            }
            $tmp = $path.'.tmp-'.bin2hex(random_bytes(4));
            if (! copy($file, $tmp) || ! rename($tmp, $path)) {
                @unlink($tmp);
                throw new \RuntimeException("Cannot write {$path}.");
            }
        } finally {
            flock($lock, LOCK_UN);
            fclose($lock);
        }

        return;
    }
    if (str_starts_with($store, 's3://')) {
        [$bucket, $prefix] = slipstream_release_s3($store);
        $argv = ['aws', 's3api', 'put-object', '--bucket', $bucket, '--key', $prefix.$key, '--body', $file, '--output', 'json'];
        $argv = array_merge($argv, $etag === null ? ['--if-none-match', '*'] : ['--if-match', $etag]);
        try {
            KmsSigner::cli($argv);
        } catch (\RuntimeException $e) {
            throw slipstream_release_is_conflict($e) ? $moved() : $e;
        }

        return;
    }

    slipstream_release_fail('--store must be s3://bucket/prefix or file:///dir', 2);
}

/**
 * Write the pointer for a ref: the sequence rises past the current one (or
 * now), a publish remembers the pointer it replaces, a rollback does not;
 * checked under the nodes' keys before it is written.
 *
 * @param  array<string, string|true>  $options
 */
function slipstream_release_point(array $options, string $sha, string $manifestSha256, bool $rollback, Keys $nodeKeys, Signer $signer): Pointer
{
    $ref = slipstream_release_need($options, 'ref');
    $environment = slipstream_release_need($options, 'environment');
    $store = slipstream_release_need($options, 'store');
    $by = slipstream_release_option($options, 'by') ?? (getenv('GITHUB_ACTOR') ?: get_current_user() ?: 'unknown');

    [$envelope, $etag] = slipstream_release_store_get($store, $ref.'.json');
    $current = null;
    if ($envelope !== null) {
        try {
            $current = slipstream_release_pointer($envelope, $ref, $environment, $nodeKeys->with($signer->keyId(), $signer->publicKey()));
        } catch (\Throwable $e) {
            slipstream_release_say('The current pointer does not verify ('.$e->getMessage().'); publishing without a previous.');
        }
    }

    $sequence = max(($current?->sequence ?? 0) + 1, time());
    $previous = (! $rollback && $current !== null && $current->sha !== $sha)
        ? ['sha' => $current->sha, 'manifest_sha256' => $current->manifestSha256]
        : null;

    $pointer = new Pointer($ref, $sha, $manifestSha256, $sequence, gmdate('Y-m-d\TH:i:s\Z'), $previous, $by, $environment, 'slipstream-release', $signer->keyId());
    $signed = Envelope::encode($pointer->toPayload(), Envelope::DOMAIN_POINTER, $signer);
    ReleaseBuilder::selfCheck(null, null, $signed, $nodeKeys);

    $file = (string) tempnam(sys_get_temp_dir(), 'ss-pointer-');
    file_put_contents($file, $signed);
    try {
        slipstream_release_store_put_pointer($store, $ref.'.json', $file, $envelope === null ? null : $etag);
    } finally {
        @unlink($file);
    }

    return $pointer;
}

/**
 * The live release against its signed manifest, and the caches the node
 * generated against the hashes the deploy recorded. With a state directory,
 * each release's manifest and recorded hashes are pinned the first time it
 * is seen, so rewriting the copies inside the tree is caught too.
 *
 * @param  list<string>  $shared
 * @return array<string, mixed>
 */
function slipstream_release_verify_tree(string $release, Keys $keys, string $environment, array $shared, ?string $stateDir): array
{
    $result = [
        'release' => $release, 'sha' => null, 'ok' => false, 'reason' => null, 'files' => 0,
        'modified' => [], 'missing' => [], 'unlisted' => [], 'links' => [], 'generated' => [], 'baseline' => 'none',
    ];
    $sidecar = $release.'/.slipstream';

    $json = @file_get_contents($sidecar.'/manifest.json');
    $signature = @file_get_contents($sidecar.'/manifest.sig');
    if ($json === false || $signature === false) {
        $result['reason'] = 'no signed manifest in .slipstream/';

        return $result;
    }

    try {
        $manifest = Manifest::fromJson($json);
        $verified = Envelope::verify($signature, Envelope::DOMAIN_MANIFEST, $keys);
        $statement = Statement::fromPayload($verified['payload'], $verified['key_id']);
    } catch (\Throwable $e) {
        $result['reason'] = 'the manifest does not verify: '.$e->getMessage();

        return $result;
    }

    $result['sha'] = $manifest->sha;
    $result['files'] = count($manifest->files);
    $releaseSha = is_file($release.'/RELEASE_SHA') ? strtolower(trim((string) file_get_contents($release.'/RELEASE_SHA'))) : null;
    $result['reason'] = match (true) {
        $statement->manifestSha256 !== hash('sha256', $json) || $statement->manifestSize !== strlen($json) => 'the statement signs another manifest',
        $statement->sha !== $manifest->sha => 'the statement signs another commit',
        $statement->environment !== $environment => "it is signed for environment \"{$statement->environment}\", not \"{$environment}\"",
        $releaseSha !== $manifest->sha => 'RELEASE_SHA is not the manifest\'s commit',
        default => null,
    };

    $tree = $manifest->verifyTree($release, array_merge(Manifest::NODE_LINKED, $shared), array_merge(Manifest::NODE_WRITTEN, $manifest->generated));
    foreach (['modified', 'missing', 'unlisted', 'links'] as $kind) {
        $result[$kind] = $tree[$kind];
    }

    $recorded = is_file($sidecar.'/'.Baseline::FILE) ? Baseline::fromJson((string) file_get_contents($sidecar.'/'.Baseline::FILE)) : null;
    if (is_file($sidecar.'/'.Baseline::FILE) && $recorded === null) {
        $result['generated'][] = Baseline::DIRECTORY.' (the recorded hashes are unreadable)';
    }
    $baseline = $recorded;
    $result['baseline'] = $recorded !== null ? 'recorded' : 'none';

    if ($stateDir !== null) {
        if (! is_dir($stateDir) && ! @mkdir($stateDir, 0700, true)) {
            throw new \RuntimeException("Cannot create {$stateDir}.");
        }
        foreach (glob(rtrim($stateDir, '/').'/*.json') ?: [] as $old) {
            $pinned = json_decode((string) file_get_contents($old), true);
            if (is_array($pinned) && is_string($pinned['release'] ?? null) && ! is_dir($pinned['release'])) {
                @unlink($old); // that release is gone
            }
        }

        $pinFile = rtrim($stateDir, '/').'/'.sha1($release).'.json';
        $pin = is_file($pinFile) ? json_decode((string) file_get_contents($pinFile), true) : null;
        if (! is_array($pin)) {
            file_put_contents($pinFile, json_encode(['release' => $release, 'manifest_sha256' => hash('sha256', $json), 'generated' => $recorded, 'pinned_at' => gmdate('c')], JSON_UNESCAPED_SLASHES));
            @chmod($pinFile, 0600);
        } else {
            if (($pin['manifest_sha256'] ?? null) !== hash('sha256', $json)) {
                $result['reason'] ??= 'the release carries another manifest than when it was first checked';
            }
            if (($pin['generated'] ?? null) !== $recorded) {
                $result['generated'][] = Baseline::DIRECTORY.' (the recorded hashes changed since the release was first checked)';
            }
            $baseline = is_array($pin['generated'] ?? null) ? $pin['generated'] : null;
        }
        $result['baseline'] = $baseline !== null ? 'pinned' : 'none';
    }

    if ($baseline !== null) {
        $result['generated'] = array_values(array_unique(array_merge($result['generated'], Baseline::compare($release, $baseline))));
    }

    $result['ok'] = $result['reason'] === null
        && $result['modified'] === [] && $result['missing'] === [] && $result['unlisted'] === []
        && $result['links'] === [] && $result['generated'] === [];

    return $result;
}

$command = $argv[1] ?? null;
if ($command === null || in_array($command, ['-h', '--help', 'help'], true)) {
    fwrite($command === null ? STDERR : STDOUT, SLIPSTREAM_RELEASE_USAGE."\n");
    exit($command === null ? 2 : 0);
}
$options = slipstream_release_options(array_slice($argv, 2));

try {
    switch ($command) {
        case 'verify-pointer':
            $ref = slipstream_release_need($options, 'ref');
            if (preg_match('#^refs/(heads|tags)/[^\s*?\[]+$#', $ref) !== 1) {
                slipstream_release_fail('--ref must be one ref, refs/heads/<branch> or refs/tags/<tag>; a tag pattern has no pointer', 2);
            }
            $pointer = slipstream_release_pointer(
                slipstream_release_read(slipstream_release_need($options, 'pointer'), Envelope::MAX_ENVELOPE),
                $ref,
                slipstream_release_need($options, 'environment'),
                Keys::parse(slipstream_release_need($options, 'keys')),
                (int) (slipstream_release_option($options, 'min-sequence') ?? 0),
            );
            slipstream_release_say('sha='.$pointer->sha);
            slipstream_release_say('manifest_sha256='.$pointer->manifestSha256);
            slipstream_release_say('sequence='.$pointer->sequence);
            slipstream_release_say('previous_sha='.($pointer->previous['sha'] ?? ''));
            slipstream_release_say('previous_manifest_sha256='.($pointer->previous['manifest_sha256'] ?? ''));
            break;

        case 'verify-release':
            $sha = strtolower(slipstream_release_need($options, 'sha'));
            $ref = slipstream_release_need($options, 'ref');
            $environment = slipstream_release_need($options, 'environment');
            $keys = Keys::parse(slipstream_release_need($options, 'keys'));
            $into = rtrim(slipstream_release_need($options, 'extract-to'), '/\\');
            $json = slipstream_release_read(slipstream_release_need($options, 'manifest'), 67108864);
            $signature = slipstream_release_read(slipstream_release_need($options, 'signature'), Envelope::MAX_ENVELOPE);
            $archive = slipstream_release_need($options, 'archive');

            $manifestSha256 = hash('sha256', $json);
            $expected = slipstream_release_option($options, 'manifest-sha256');
            if ($expected !== null && $expected !== $manifestSha256) {
                throw new ArtifactRefused('manifest', "the manifest's hash is not the one the pointer names");
            }
            $verified = Envelope::verify($signature, Envelope::DOMAIN_MANIFEST, $keys);
            $statement = Statement::fromPayload($verified['payload'], $verified['key_id']);
            if ($statement->sha !== $sha) {
                throw new ArtifactRefused('statement', "the statement signs {$statement->sha}, not {$sha}");
            }
            if ($statement->manifestSha256 !== $manifestSha256 || $statement->manifestSize !== strlen($json)) {
                throw new ArtifactRefused('statement', 'the statement signs another manifest');
            }
            if ($statement->environment !== $environment) {
                throw new ArtifactRefused('statement', "it is signed for environment \"{$statement->environment}\"; this node is \"{$environment}\"");
            }
            if ($statement->ref !== $ref) {
                throw new ArtifactRefused('statement', "it was built for {$statement->ref}; this node deploys {$ref}");
            }
            $manifest = Manifest::fromJson($json);
            if ($manifest->sha !== $sha) {
                throw new ArtifactRefused('manifest', "the manifest is for {$manifest->sha}, not {$sha}");
            }
            if ($manifest->archiveSha256 !== $statement->archiveSha256) {
                throw new ArtifactRefused('statement', 'the statement signs another archive');
            }
            $node = PHP_MAJOR_VERSION.'.'.PHP_MINOR_VERSION;
            if (version_compare($node, $manifest->phpSeries(), '<')) {
                throw new ArtifactRefused('php', "built for PHP {$manifest->phpSeries()}; this node runs {$node}");
            }
            if (version_compare($node, $manifest->phpSeries(), '>')) {
                fwrite(STDERR, "slipstream-release: built for PHP {$manifest->phpSeries()}; this node runs {$node}\n");
            }
            if (! is_file($archive) || filesize($archive) !== $manifest->archiveSize) {
                throw new ArtifactRefused('archive', 'the archive is not the size the manifest says');
            }
            if (hash_file('sha256', $archive) !== $manifest->archiveSha256) {
                throw new ArtifactRefused('archive', 'the archive does not match the signed manifest');
            }
            if (is_dir($into) && count(scandir($into) ?: []) > 2) {
                slipstream_release_fail("{$into} is not empty");
            }
            $created = ! is_dir($into);
            if ($created && ! @mkdir($into, 0755, true)) {
                slipstream_release_fail("cannot create {$into}");
            }

            try {
                $files = TarReader::extract($archive, $into, [
                    'max_unpacked_bytes' => min((int) (slipstream_release_option($options, 'max-unpacked-bytes') ?? PHP_INT_MAX), $manifest->unpackedBytes),
                    'max_entries' => min((int) (slipstream_release_option($options, 'max-entries') ?? 250000), $manifest->entries),
                ], $manifest->files);
                @mkdir($into.'/.slipstream', 0755);
                if (file_put_contents($into.'/.slipstream/manifest.json', $json) === false
                    || file_put_contents($into.'/.slipstream/manifest.sig', $signature) === false
                    || file_put_contents($into.'/RELEASE_SHA', $sha."\n") === false) {
                    throw new \RuntimeException("Cannot write the release's sidecar in {$into}.");
                }
            } catch (\Throwable $e) {
                // Nothing unverified stays behind.
                foreach (scandir($into) ?: [] as $name) {
                    if ($name !== '.' && $name !== '..') {
                        slipstream_release_remove_tree($into.'/'.$name);
                    }
                }
                if ($created) {
                    @rmdir($into);
                }
                throw $e;
            }
            slipstream_release_say('files='.count($files));
            break;

        case 'verify-tree':
            $release = slipstream_release_need($options, 'release');
            $real = realpath($release);
            if ($real === false || ! is_dir($real)) {
                slipstream_release_fail("no release at {$release}");
            }
            $result = slipstream_release_verify_tree(
                str_replace('\\', '/', $real),
                Keys::parse(slipstream_release_need($options, 'keys')),
                slipstream_release_need($options, 'environment'),
                slipstream_release_list($options, 'shared', []),
                slipstream_release_option($options, 'state-dir'),
            );

            if (isset($options['json'])) {
                $line = ['event' => $result['ok'] ? 'artifact.verify_ok' : 'artifact.verify_drift'] + $result;
                foreach (['modified', 'missing', 'unlisted', 'links', 'generated'] as $kind) {
                    $line[$kind.'_count'] = count($result[$kind]);
                    $line[$kind] = array_slice($result[$kind], 0, 20);
                }
                slipstream_release_say((string) json_encode($line, JSON_UNESCAPED_SLASHES));
            } elseif ($result['ok']) {
                slipstream_release_say("ok: {$result['release']} ({$result['sha']}) matches its signed manifest: {$result['files']} files; generated caches ".($result['baseline'] === 'none' ? 'not recorded' : 'match the '.$result['baseline'].' hashes'));
            } else {
                slipstream_release_say("DRIFT: {$result['release']}".($result['sha'] ? " ({$result['sha']})" : '').($result['reason'] ? ": {$result['reason']}" : ''));
                foreach (['modified' => 'modified', 'missing' => 'missing', 'unlisted' => 'not in the manifest', 'links' => 'symlinks', 'generated' => 'generated since the deploy'] as $kind => $label) {
                    if ($result[$kind] !== []) {
                        slipstream_release_say('  '.$label.' ('.count($result[$kind]).'): '.implode(', ', array_slice($result[$kind], 0, 20)).(count($result[$kind]) > 20 ? ', …' : ''));
                    }
                }
            }
            exit($result['ok'] ? 0 : 1);

        case 'publish':
            $archive = slipstream_release_need($options, 'archive');
            $built = Manifest::fromJson(slipstream_release_read(slipstream_release_need($options, 'manifest'), 67108864));
            $ref = slipstream_release_need($options, 'ref');
            $environment = slipstream_release_need($options, 'environment');
            $store = slipstream_release_need($options, 'store');
            $sha = strtolower(slipstream_release_option($options, 'sha') ?? (getenv('GITHUB_SHA') ?: ''));
            if (preg_match('/^[0-9a-f]{40}$/', $sha) !== 1) {
                slipstream_release_fail('--sha is required: the commit being published, by its full id (GitHub Actions sets GITHUB_SHA). The build job does not get to say which commit it built.', 2);
            }
            if ($built->sha !== $sha) {
                slipstream_release_fail("the build says it is {$built->sha}; this publish is for {$sha}");
            }
            if ($built->ref !== $ref) {
                slipstream_release_fail("the build is for {$built->ref}; the pointer is {$ref}");
            }
            $nodeKeys = Keys::parse(slipstream_release_need($options, 'keys'));
            $signer = Signers::fromSpec(slipstream_release_need($options, 'key'), slipstream_release_option($options, 'key-id'));

            $generated = slipstream_release_list($options, 'generated', Manifest::DEFAULT_GENERATED);
            foreach ($generated as $path) {
                if (! Manifest::validPath($path)) {
                    slipstream_release_fail('not a release path for --generated: '.$path, 2);
                }
            }

            slipstream_release_say('Reading the archive back to build the manifest to sign…');
            $manifest = ReleaseBuilder::manifestFromArchive($archive, [
                'slipstream' => $built->slipstream, 'environment' => $environment, 'sha' => $sha, 'ref' => $built->ref,
                'built_at' => $built->builtAt, 'php' => $built->php, 'generated' => $generated,
            ], [
                'max_unpacked_bytes' => (int) (slipstream_release_option($options, 'max-unpacked-bytes') ?? 4294967296),
                'max_entries' => (int) (slipstream_release_option($options, 'max-entries') ?? 250000),
            ], ReleaseBuilder::inspector(slipstream_release_list($options, 'allow', [])));
            $json = $manifest->toJson();
            $statement = Envelope::encode(ReleaseBuilder::statementFor($manifest, $json, $environment)->toPayload(), Envelope::DOMAIN_MANIFEST, $signer);
            ReleaseBuilder::selfCheck($json, $statement, null, $nodeKeys);

            $dir = sys_get_temp_dir().'/ss-publish-'.bin2hex(random_bytes(4));
            mkdir($dir, 0700);
            try {
                file_put_contents($dir.'/manifest.json', $json);
                file_put_contents($dir.'/manifest.sig', $statement);
                foreach (['release.tar.gz' => $archive, 'manifest.json' => $dir.'/manifest.json', 'manifest.sig' => $dir.'/manifest.sig'] as $name => $file) {
                    slipstream_release_say((slipstream_release_store_put_once($store, 'releases/'.$sha.'/'.$name, $file) ? 'Uploaded ' : 'Already in the store: ').$name);
                }
            } finally {
                @unlink($dir.'/manifest.json');
                @unlink($dir.'/manifest.sig');
                @rmdir($dir);
            }
            slipstream_release_say('Release '.substr($sha, 0, 7).': '.count($manifest->files).' files, signed by key '.$signer->keyId());

            $pointer = slipstream_release_point($options, $sha, hash('sha256', $json), false, $nodeKeys, $signer);
            slipstream_release_say(sprintf('%s → %s (sequence %d%s)', $pointer->ref, $pointer->short(), $pointer->sequence, $pointer->previous ? ', previous '.substr($pointer->previous['sha'], 0, 7) : ''));
            break;

        case 'rollback':
            $sha = strtolower(slipstream_release_need($options, 'sha'));
            if (preg_match('/^[0-9a-f]{40}$/', $sha) !== 1) {
                slipstream_release_fail('--sha must be the full 40-character commit id', 2);
            }
            $ref = slipstream_release_need($options, 'ref');
            $store = slipstream_release_need($options, 'store');
            $environment = slipstream_release_need($options, 'environment');
            $nodeKeys = Keys::parse(slipstream_release_need($options, 'keys'));
            $signer = Signers::fromSpec(slipstream_release_need($options, 'key'), slipstream_release_option($options, 'key-id'));

            [$signature] = slipstream_release_store_get($store, 'releases/'.$sha.'/manifest.sig');
            if ($signature === null) {
                slipstream_release_fail('no release '.substr($sha, 0, 7).' in the store');
            }
            $verified = Envelope::verify($signature, Envelope::DOMAIN_MANIFEST, $nodeKeys->with($signer->keyId(), $signer->publicKey()));
            $statement = Statement::fromPayload($verified['payload'], $verified['key_id']);
            if ($statement->sha !== $sha || $statement->environment !== $environment) {
                slipstream_release_fail('the release '.substr($sha, 0, 7).' carries a statement for another commit or environment');
            }
            if ($statement->ref !== $ref) {
                slipstream_release_fail('the release '.substr($sha, 0, 7)." was built for {$statement->ref}; nodes deploying {$ref} would refuse it");
            }

            $pointer = slipstream_release_point($options, $sha, $statement->manifestSha256, true, $nodeKeys, $signer);
            slipstream_release_say(sprintf('%s → %s (sequence %d, rollback)', $pointer->ref, $pointer->short(), $pointer->sequence));
            break;

        default:
            slipstream_release_fail("unknown command {$command}\n\n".SLIPSTREAM_RELEASE_USAGE, 2);
    }
} catch (ArtifactRefused $e) {
    slipstream_release_fail('refused ('.$e->stage.'): '.$e->reason);
} catch (\Throwable $e) {
    slipstream_release_fail($e->getMessage());
}

}
